insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('saafi-doner', '36534c38-a00a-56a0-b121-ec049390b199', 'Saafi Döner''de indirimli döner fiks menü', 'restoran', 'istanbul', 'Güneşli / İkitelli', 'Güneşli şubesi: Kirazlı Mah. Mahmutbey Cad. No:122 (İSKİ karşısı), Güneşli / İstanbul — İkitelli şubesi: Ziya Gökalp Mah. Atatürk Cad. No:117 Çelik Yenal İş Merkezi, İkitelli / Başakşehir / İstanbul', 'Çorba, döner çeşidi, salata, tatlı ve içecekten oluşan tam menü indirimli fiyatla.', 'Günün çorbası, ardından İskender, porsiyon döner ya da pilav üstü döner seçeneklerinden biri; yanında salata, tatlı, içecek, su ve çay geliyor. Öğle veya akşam doyurucu bir döner menüsü arayanlar için uygun. Yalnızca Güneşli ve İkitelli şubelerinde geçerli.', array['Sadece Güneşli ve İkitelli şubelerinde geçerli', 'Hafta içi 12:00-23:00 arası geçerli; pazar günleri ve Ramazan döneminde geçerli değil', 'Kod başına 1 kişi', 'İşletmedeki kalan ödeme yalnızca nakit', 'Paket serviste geçerli değil', 'Kod sipariş verirken belirtilmeli', 'Aynı gün en fazla 10 kişilik grup rezervasyonu alınıyor', 'İptaller en az 24 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-jkzrfnez/anagrslll8092.jpg', array['https://grpstat.com/DealImages/G-jkzrfnez/anagrslll8092__1.jpg', 'https://grpstat.com/DealImages/G-jkzrfnez/anagrslll8092__2.jpg']::text[], 1200, 850, '2026-12-30', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/saafi-doner/saafi-doner-indirim-ceki')
  on conflict (id) do update set isletme_id = excluded.isletme_id, baslik = excluded.baslik, kategori = excluded.kategori, sehir = excluded.sehir, semt = excluded.semt, adres = excluded.adres, kisa = excluded.kisa, aciklama = excluded.aciklama, kosullar = excluded.kosullar, gorsel = excluded.gorsel, galeri = excluded.galeri, eski_fiyat = excluded.eski_fiyat, yeni_fiyat = excluded.yeni_fiyat, bitis = excluded.bitis, stok = excluded.stok, kisi_basi_limit = excluded.kisi_basi_limit, rezervasyon_gerekli = excluded.rezervasyon_gerekli, link = excluded.link, one_cikan = excluded.one_cikan, durum = excluded.durum, kaynak = excluded.kaynak, kaynak_url = excluded.kaynak_url;
insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('red-dragon-chinese-restaurant', '62cba08f-c12f-5c3a-9907-bab3a803cbfd', 'Red Dragon Alsancak''ta 18 parça sushi tabağı', 'restoran', 'izmir', 'Alsancak / Konak', '1379 Sok. Efes İşhanı (Hilton Otel yanı) No:57/A, Alsancak / İzmir', 'Üç farklı rulodan oluşan 18 parçalık sushi tabağı Alsancak''ta indirimli.', 'Tabakta 6''şar parça Kappa Maki, Kani Maki ve California roll bulunuyor. Uzak Doğu mutfağını denemek isteyenler veya hafif bir öğle/akşam yemeği arayanlar için uygun. Restoran Alsancak''ta, Hilton Oteli''nin yanında.', array['Kod başına 1 kişi', 'Özel günlerde geçerli değil', 'Hafta içi ve pazar 10:30-23:30; cuma ve cumartesi 10:30-17:00 arası geçerli', 'Rezervasyon için restoran aranmalı', 'İptaller en az 24 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-fx0slryb/alsancak-red-dragon-chinese-restaurant-sushi-menusu-47c62c.jpg', array['https://grpstat.com/DealImages/G-fx0slryb/alsancak-red-dragon-chinese-restaurant-sushi-menusu-47c62c__1.jpg', 'https://grpstat.com/DealImages/G-fx0slryb/alsancak-red-dragon-chinese-restaurant-sushi-menusu-47c62c__2.jpg', 'https://grpstat.com/DealImages/G-fx0slryb/alsancak-red-dragon-chinese-restaurant-sushi-menusu-47c62c__3.jpg']::text[], 1400, 795, '2026-11-15', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/red-dragon-cin-restorani/alsancak-red-dragon-chinese-restaurant-sushi-menusu')
