insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('goze-sariyer', '68e4c02e-c52c-534e-8bc5-d69a53f55980', 'Göze Sarıyer''de Boğaz manzaralı akşam yemeği', 'restoran', 'istanbul', 'Sarıyer', 'Mesarburnu Cad. Kumsal Arkası Sok. No:8/1, Sarıyer / İstanbul', 'Boğaz kıyısında çorba, salata, ana yemek, sufle ve içecekli tek kişilik menü.', 'Menü günün çorbası ve mevsim salatası ile başlıyor; ana yemekte tavuk ve köfte ağırlıklı 9 seçenekten biri seçiliyor. Tatlı olarak çikolatalı ya da tahinli sufle, yanında meşrubat ve çay geliyor. Manzaralı ve uygun fiyatlı bir akşam yemeği isteyenlere hitap ediyor.', array['Kod başına 1 kişi', 'Gün boyu geçerli', '0-6 yaş çocuklar ücretsiz, 7 yaş ve üzeri için ayrı kod gerekli', 'Rezervasyon için işletme aranmalı', 'İptaller en az 24 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-gvlzva34/goze-sariyer-bogaz-manzarali-aksam-yemegi-a1d517.jpg', array['https://grpstat.com/DealImages/G-gvlzva34/goze-sariyer-bogaz-manzarali-aksam-yemegi-a1d517__1.jpg', 'https://grpstat.com/DealImages/G-gvlzva34/goze-sariyer-bogaz-manzarali-aksam-yemegi-a1d517__2.jpg', 'https://grpstat.com/DealImages/G-gvlzva34/goze-sariyer-bogaz-manzarali-aksam-yemegi-a1d517__3.jpg']::text[], null, 1100, '2026-12-31', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/goze-sariyer/goze-sariyer-bogaz-manzarali-aksam-yemegi')
