insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('maltis-et-lokantasi', 'ad24af05-3762-5369-a61b-f0f29d82ffd8', 'Maltıs Et Lokantası''nda ızgara menü', 'restoran', 'istanbul', 'Büyükçekmece', 'Kamiloba Mah. D-100 Karayolu Cad. No:699, Büyükçekmece / İstanbul', 'Çorba, salata, meze, ızgara ana yemek ve tatlıdan oluşan et lokantası menüsü.', 'Meşrubatlı menüde çorba, salata, bir soğuk meze, ana yemek, tatlı (sütlaç veya Hayrabolu) ve içecek var; ana yemek tavuk şiş, kanat, tavuk pirzola ya da Adana/Urfa kebap arasından seçiliyor. Yerli içecekli seçenekte çorba ve tatlı yerine meyve ve bir yerli içecek bulunuyor. Ücretsiz otopark ve çocuk oyun alanı olduğu için aileler için uygun.', array['Her gün 12:00-24:00 arası geçerli', 'Masadaki her kişi için 1 kod gerekli', 'İptaller en az 24 saat önceden bildirilmeli', 'Yerli içecekli seçenek ayrı fiyatlı (kişi başı 1.750 TL)']::text[], 'https://grpstat.com/DealImages/G-j513x4pk/maltis34313.jpg', array['https://grpstat.com/DealImages/G-j513x4pk/maltis34313__1.jpg', 'https://grpstat.com/DealImages/G-j513x4pk/maltis34313__2.jpg', 'https://grpstat.com/DealImages/G-j513x4pk/maltis34313__3.jpg']::text[], null, 1150, '2026-11-15', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/maltis-et-lokantasi/maltiz-et-lokantasi-yemek-menusu')
