insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ada-palas-buyukada-butik-otel-secret-garden-rest', '1f057e24-ae9f-5e11-a1e6-f197d2d6a609', 'Büyükada''da iki kişilik bahçede akşam yemeği', 'restoran', 'istanbul', 'Büyükada / Adalar', 'Maden Mah. Çiçekli Yalı Sok. No:24, Büyükada / İstanbul', 'Ada Palas''ın bahçe restoranında mezeli, balık veya ızgaralı çift menüsü.', 'İki kişilik menüde en az 7 çeşit ev yapımı meze, sigara böreği ve kaşar kroket, bahçe salatası, karışık ızgara ya da levrek/çipura seçeneği ve tatlı var; sınırsız çay-kahve ile bir hediye fotoğraf çekimi de dahil. Yerli şaraplı iki ayrı seçenek daha bulunuyor. Romantik bir ada akşamı planlayan çiftler için uygun.', array['Fiyat 2 kişi içindir', 'Haftanın her günü geçerli', 'Rezervasyon zorunlu', 'İptaller en az 24 saat önceden bildirilmeli', 'Kırmızı şaraplı seçenek 5.849 TL, beyaz şaraplı seçenek 6.349 TL']::text[], 'https://grpstat.com/DealImages/G-42vq5f3m/15279.jpg', array['https://grpstat.com/DealImages/G-42vq5f3m/15279__1.jpg', 'https://grpstat.com/DealImages/G-42vq5f3m/15279__2.jpg', 'https://grpstat.com/DealImages/G-42vq5f3m/15279__3.jpg']::text[], null, 5099, '2026-12-28', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/ada-palas-buyukada-butik-otel/ada-palas-buyukada-secret-garden-restaurant-aksam-yemegi')
