insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('san-iskender-ankamall', '41afe4e0-bea3-50c2-a494-81cb22d802d9', 'Şan İskender Ankamall''da ıslama köfte menüsü', 'restoran', 'ankara', 'Yenimahalle', 'Konya Devlet Yolu, Ankamall AVM 2/2055, Yenimahalle / Ankara', 'Islama köfte, bulgur pilavı, salata, turşu, sütlaç ve içecek tek menüde.', 'Kişi başı menüde bir porsiyon ıslama köfte, bulgur pilavı, salata, turşu, sütlaç ve kola yer alıyor. AVM içinde pratik ve doyurucu bir öğün arayanlar için uygun.', array['Kod başına 1 kişi', 'Rezervasyon ve değişiklikler müsaitliğe bağlı', 'İptaller en az 24 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-aec4b844/san-iskender-ankamall-menu-islama-kofte-a7cfea.jpg', array['https://grpstat.com/DealImages/G-aec4b844/san-iskender-ankamall-menu-islama-kofte-a7cfea__1.jpg', 'https://grpstat.com/DealImages/G-aec4b844/san-iskender-ankamall-menu-islama-kofte-a7cfea__2.jpg', 'https://grpstat.com/DealImages/G-aec4b844/san-iskender-ankamall-menu-islama-kofte-a7cfea__3.jpg']::text[], 915, 550, '2027-01-05', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/san-iskender---ankamall/san-iskender-ankamall-menu-islama-kofte')
