insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('afrodit-restaurant-kumkapi', 'bab9557c-57f9-5fc9-8dd4-6fc415828c43', 'Kumkapı Afrodit''te canlı müzikli akşam menüsü', 'restoran', 'istanbul', 'Kumkapı / Fatih', 'Çapari Sok. No:55, Kumkapı / Fatih / İstanbul', 'Meze, sıcak, balık/köfte/tavuk ana yemek ve içecekli Kumkapı menüsü, canlı müzikle.', 'Masaya 4 çeşit meze, mevsim salatası ve sigara böreği geliyor; ana yemekte mevsim balığı (levrek/çipura), köfte, tavuk ya da vejetaryen güveç seçilebiliyor. Meyve-tatlı, bir kadeh yerli içecek veya meşrubat ile çay/Türk kahvesi de dahil. Kumkapı''da canlı müzikli bir akşam isteyenlere uygun.', array['Fiyat kişi başıdır', 'Haftanın her günü 10:00-24:00 arası geçerli', 'Telefonla rezervasyon yapılmalı, kod belirtilmeli', 'İptaller en az 24 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-qavthtvb/a04161.jpg', array['https://grpstat.com/DealImages/G-qavthtvb/a04161__1.jpg', 'https://grpstat.com/DealImages/G-qavthtvb/a04161__2.jpg', 'https://grpstat.com/DealImages/G-qavthtvb/a04161__3.jpg']::text[], 2250, 1300, '2026-11-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/afrodit-restaurant---kumkapi/kumkapi-afrodit-restaurant-yemek')
