insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('hotel-selimpasa-konagi', 'fcae4247-7449-5622-8c34-4fadb1f54a8f', 'Selimpaşa Konağı''nda deniz manzaralı set menü', 'restoran', 'istanbul', 'Selimpaşa / Silivri', 'Selimpaşa Merkez Mah. 3062 Sok. No:15, Selimpaşa / Silivri / İstanbul', 'Çorba, ana yemek, salata, sütlaç ve meşrubattan oluşan deniz manzaralı akşam menüsü.', 'İki set menü var: mercimek çorbası ile mantar soslu tavuk sarma veya pesto soslu tavuk göğsü, ya da yayla çorbası ile pilav ve patates eşliğinde köfte. İkisinde de mevsim yeşillikleri salatası, sütlaç ve bir meşrubat bulunuyor. Silivri tarafında sakin, manzaralı bir akşam yemeği arayanlara uygun.', array['Fiyat kişi başıdır', 'Haftanın her günü 17:00-23:00 arası geçerli, özel günler hariç', 'Rezervasyon zorunlu', '0-3 yaş ücretsiz, 3-7 yaş işletmede %50 indirimli, 7 yaş üzeri kod gerekli', 'Değişiklik ve iptaller en az 3 gün önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-jmxiw22w/silivri-hotel-selimpasa-konagi-aksam-yemegi-menusu-9530a5.jpg', array['https://grpstat.com/DealImages/G-jmxiw22w/silivri-hotel-selimpasa-konagi-aksam-yemegi-menusu-9530a5__1.jpg', 'https://grpstat.com/DealImages/G-jmxiw22w/silivri-hotel-selimpasa-konagi-aksam-yemegi-menusu-9530a5__2.jpg', 'https://grpstat.com/DealImages/G-jmxiw22w/silivri-hotel-selimpasa-konagi-aksam-yemegi-menusu-9530a5__3.jpg']::text[], null, 900, '2026-12-28', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/silivri-selimpasa-konagi/silivri-hotel-selimpasa-konagi-aksam-yemegi-menusu')
