insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('woki-point-sariyer', '60fda76f-9111-50fe-b167-471f79c9a956', 'Woki Point Sarıyer''de deniz kenarında akşam menüsü', 'restoran', 'istanbul', 'Sarıyer', 'Merkez Mah. Mesarburnu Cad. No:10/B, 34450 Sarıyer / İstanbul', 'Balık, bonfile, tavuk veya köfteli 4 farklı akşam menüsü, deniz kıyısında.', 'Dört menünün hepsinde çorba, paçanga ve sigara böreği, salata, tatlı, meşrubat, su, çay ve Türk kahvesi var. Ana yemek menüye göre ızgara levrek/çipura, dana bonfile, soslu tavuk ya da Woki köfte oluyor. Sarıyer sahilinde iki ya da daha fazla kişilik akşam yemeği planlayanlara uygun.', array['Kod başına 1 kişi, en az 2 kod alınmalı', 'Haftanın her günü geçerli', '0-5 yaş çocuklar ücretsiz', 'Rezervasyon için işletme aranmalı', 'İptaller en az 24 saat önceden bildirilmeli', 'Fiyat seçilen menüye göre kişi başı 1.199-1.649 TL arası']::text[], 'https://grpstat.com/DealImages/G-h4yegdz1/woki-point-sariyer-aksam-yemegi-871a34.jpg', array['https://grpstat.com/DealImages/G-h4yegdz1/woki-point-sariyer-aksam-yemegi-871a34__1.jpg', 'https://grpstat.com/DealImages/G-h4yegdz1/woki-point-sariyer-aksam-yemegi-871a34__2.jpg', 'https://grpstat.com/DealImages/G-h4yegdz1/woki-point-sariyer-aksam-yemegi-871a34__3.jpg']::text[], null, 1199, '2026-11-25', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/woki-point-sariyer/woki-point-sariyer-aksam-yemegi')
