insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('gaziantep-kale-alti-kuzu-lahmacun-beyran', 'a684ecd6-aaff-56f0-91b2-025b05f526d7', 'Gaziantep Kale Altı''nda kebap veya kuzu menüsü', 'restoran', 'istanbul', 'Suadiye / Kadıköy', 'Suadiye, Şemsettin Günaltay Cad. No:65, 34740 Kadıköy / İstanbul', 'Ara sıcaklar, lahmacun, kebap veya kuzu şiş ve künefe/kadayıflı Antep menüsü.', 'Başlangıçta acılı ezme, haydari, tablacı salatası, çiğ köfte; ara sıcak olarak fındık lahmacun ve balon pide geliyor. Kebap menüsünde Adana, Urfa, tavuk şiş veya kanat; kuzu menüsünde kuzu şiş veya çöp şiş seçiliyor. Tatlıda fırın sütlaç, kadayıf veya künefe, yanında ayran/kutu içecek ve çay var; Antep mutfağı sevenler için uygun.', array['Kod başına 1 kişi, en az 2 kod alınmalı', 'Her gün 11:00-02:00 arası geçerli', 'Tarih değişikliği müsaitliğe bağlı', 'İptaller en az 2 gün önceden bildirilmeli', 'Kuzu menüsü kişi başı 1.150 TL (eski 1.950 TL)']::text[], 'https://grpstat.com/DealImages/G-k4vqbyfk/gaziantep-kale-alti-kuzu-lahmacun-beyran-menu-2042a3.jpg', array['https://grpstat.com/DealImages/G-k4vqbyfk/gaziantep-kale-alti-kuzu-lahmacun-beyran-menu-2042a3__1.jpg', 'https://grpstat.com/DealImages/G-k4vqbyfk/gaziantep-kale-alti-kuzu-lahmacun-beyran-menu-2042a3__2.jpg', 'https://grpstat.com/DealImages/G-k4vqbyfk/gaziantep-kale-alti-kuzu-lahmacun-beyran-menu-2042a3__3.jpg']::text[], 1850, 980, '2026-12-31', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/gaziantep-kale-alti/gaziantep-kale-alti-kuzu-lahmacun-beyran-menu')
