insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ve-hotels-bogazici-vilayetler-evi', 'd840638f-d58d-58fe-9292-7ce10b0b75d0', 'Boğaz kıyısında otelde serpme kahvaltı', 'kahvalti', 'istanbul', 'Sarıyer / Tarabya-Kireçburnu', 'Haydar Aliyev Caddesi No: 110, Kireçburnu, Sarıyer / İstanbul', 'Tarabya''da deniz kenarında, sınırsız çaylı kişi başı serpme kahvaltı 740 TL.', 'Beş çeşit peynir, zeytin, bal-kaymak, reçel, menemen ve omlet içeren zengin bir serpme kahvaltı; hafta içi poğaça, hafta sonu gözleme ile servis ediliyor. Boğaz manzarasında aile ve arkadaş kahvaltısı için uygun.', array['Kişi başı fiyattır, en az 2 kişilik alınmalı', 'Her gün 09:00-13:30 arası geçerli', 'Rezervasyon zorunlu, çocuk sayısı bildirilmeli', '0-4 yaş ücretsiz, 5 yaş ve üzeri için kod gerekli', 'İptal en geç 24 saat önce yapılmalı']::text[], 'https://grpstat.com/DealImages/G-m5hyecbv/yeni11409.jpg', array['https://grpstat.com/DealImages/G-m5hyecbv/yeni11409__1.jpg', 'https://grpstat.com/DealImages/G-m5hyecbv/yeni11409__2.jpg', 'https://grpstat.com/DealImages/G-m5hyecbv/yeni11409__3.jpg']::text[], null, 740, '2026-11-15', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/istanbul-vilayetler-evi/tarabya-vilayetler-evi-kahvalti')
