insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('karagozler-et-izgara-sarkuteri', '288e7e93-21a7-522f-8b3f-03502983199b', 'Esenyurt''ta 7/24 geçerli serpme kahvaltı', 'kahvalti', 'istanbul', 'Esenyurt', 'Talatpaşa Mah. Fatih Sultan Mehmet Cad. No:51/52, Esenyurt / İstanbul (Regnum Towers ve Solarkent yakını)', 'Taş fırın pide ve sınırsız çayla kişi başı serpme kahvaltı 450 TL, rezervasyonsuz.', 'On çeşide yakın peynir, sucuk-salam, ezmeler, üç çeşit reçel, bal-kaymak, tahin-pekmez, patates kızartması, yumurta ve taş fırından pide içeren bol çeşitli bir kahvaltı. Restoran 24 saat açık olduğu için günün her saatinde kullanılabiliyor; kalabalık gruplar ve geç kahvaltı sevenler için uygun.', array['Kişi başı fiyattır, en az 2 kişi kullanmalı', 'Haftanın her günü, günün her saati geçerli', 'Rezervasyon gerekmez', '0-6 yaş ücretsiz', 'Türk kahvesi ücrete dahil değil']::text[], 'https://grpstat.com/DealImages/G-fibpv1nm/karagozler-et-izgara-sarkuteri-serpme-kahvalti-6f057c.jpg', array['https://grpstat.com/DealImages/G-fibpv1nm/karagozler-et-izgara-sarkuteri-serpme-kahvalti-6f057c__1.jpg', 'https://grpstat.com/DealImages/G-fibpv1nm/karagozler-et-izgara-sarkuteri-serpme-kahvalti-6f057c__2.jpg', 'https://grpstat.com/DealImages/G-fibpv1nm/karagozler-et-izgara-sarkuteri-serpme-kahvalti-6f057c__3.jpg']::text[], null, 450, '2026-12-15', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/karagozler-et-izgara-cag-kebabi/karagozler-et-izgara-sarkuteri-serpme-kahvalti')
