insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('sellale-cafe-restaurant', '20f49d94-4650-5381-9334-04c4fcb7b064', 'Merter''de %21 indirimli serpme kahvaltı', 'kahvalti', 'istanbul', 'Merter / Bahçelievler', 'Bahçelievler Mah. Mehmet Akif Cad. No: 1, E-5 Yanyol, Green Park Otel yanı, Merter / İstanbul', 'Altı çeşit peynir, menemen veya omlet ve termos çayla kişi başı 625 yerine 495 TL.', 'Beyaz, kaşar, tulum, burgu, topik ve lor peyniri, bal, reçel, tereyağı, zeytin, acuka, haydari, sigara böreği ve patates kızartması sunuluyor; menemen ya da omlet seçilebiliyor. Ücretsiz otoparkı olduğundan arabayla gelenler için pratik.', array['Kişi başı fiyattır, en az 2 kişi', 'Pazartesi-cumartesi 09:00-14:00 arası geçerli, pazar günü serpme servis yok', 'Rezervasyon zorunlu', 'Bir termos çay (yaklaşık 10 bardak) dahil', 'İptal en geç 1 gün önce yapılmalı']::text[], 'https://grpstat.com/DealImages/G-cwdedbri/sellale-cafe-restaurant-kahvalti-766057.jpg', array['https://grpstat.com/DealImages/G-cwdedbri/sellale-cafe-restaurant-kahvalti-766057__1.jpg', 'https://grpstat.com/DealImages/G-cwdedbri/sellale-cafe-restaurant-kahvalti-766057__2.jpg', 'https://grpstat.com/DealImages/G-cwdedbri/sellale-cafe-restaurant-kahvalti-766057__3.jpg']::text[], 625, 495, '2026-12-31', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/sellale-restaurant-ve-cafe/sellale-cafe-restaurant-kahvalti')
