insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('blue-marmaray-hotel', 'cc82f580-d0b2-54e9-9518-51b24d11b4cd', 'Yenikapı''da otelde açık büfe kahvaltı', 'kahvalti', 'istanbul', 'Fatih / Yenikapı', 'Katip Kasım Mah. Güvenlik Caddesi No: 43, 34130 Yenikapı, Fatih / İstanbul', 'Adalar ve Marmara manzaralı otelde hafta sonu açık büfe kahvaltı kişi başı 450 TL.', 'Sekiz çeşit peynir, beş çeşit zeytin, şarküteri ürünleri, değişen sıcaklar (çorba, börek, haşlanmış yumurta, kek), salatalar, reçel-bal, meyve suyu ve gevreklerden oluşan bir açık büfe. Erken saatte kahvaltı yapmak isteyenler için uygun.', array['Kişi başı fiyattır', 'Yalnızca hafta sonu 07:00-10:00 arası geçerli', 'Rezervasyon telefonla yapılabilir', 'İptal en geç 24 saat önce bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-xax1a51v/b15459.jpg', array['https://grpstat.com/DealImages/G-xax1a51v/b15459__1.jpg', 'https://grpstat.com/DealImages/G-xax1a51v/b15459__2.jpg', 'https://grpstat.com/DealImages/G-xax1a51v/b15459__3.jpg']::text[], null, 450, '2026-11-11', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/blue-marmaray-hotel/blue-marmaray-hotel-kahvalti')
