insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('husnu-ala-cafe-restaurant', 'b59b58d2-2bac-58dc-88f0-6ea797c268ed', 'Tarihi Yarımada''da Boğaz manzaralı serpme kahvaltı', 'kahvalti', 'istanbul', 'Fatih', 'Demirtaş Mah. Fetva Yokuşu, Nazır İzzet Efendi Sok. No: 12, Fatih / İstanbul', 'Petek bal, süt kaymağı ve pişili serpme kahvaltı kişi başı 800 TL, sınırsız çay dahil.', 'Ezine peyniri, Gemlik zeytini, petek bal, süt kaymağı, menemen, patatesli börek, pişi, pide ve vişneli süzme yoğurt içeren bir serpme kahvaltı. Fatih''te manzaralı bir ortamda kahvaltı yapmak isteyen çiftler ve turistler için uygun.', array['Kişi başı fiyattır, en az 2 kişilik alınmalı', 'Pazar hariç haftanın 6 günü geçerli', 'Değişiklik ve iptal en geç 24 saat önce yapılmalı']::text[], 'https://grpstat.com/DealImages/G-5muyd4rk/husnu-ala-cafe-restaurant-serpme-kahvalti-5298c7.jpg', '{}'::text[], null, 800, '2026-11-20', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/husnu-ala-cafe/husnu-ala-cafe-restaurant-serpme-kahvalti')
