insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('radisson-blu-hotel-istanbul-pera', 'cabff482-aa87-5f9e-abb6-7fc0607e2e4b', 'Beyoğlu''nda 5 yıldızlı otelde açık büfe kahvaltı', 'kahvalti', 'istanbul', 'Beyoğlu / Tepebaşı', 'Evliya Çelebi Mah. Refik Saydam Cad. No: 19, Tepebaşı, Beyoğlu / İstanbul', 'Waffle, pankek ve glütensiz seçenekli zengin açık büfe kahvaltı kişi başı 1.200 TL.', 'Peynirler, yumurta çeşitleri, simit-kruvasan gibi unlu mamuller, şarküteri, börek, sucuk, waffle, pankek, çorba, meyve, kahve ve bitkisel süt seçenekleri sunan geniş bir otel büfesi. Haftanın her günü geçerli; şehir merkezinde kaliteli kahvaltı arayanlar için uygun.', array['Kişi başı fiyattır, masadaki her kişi için kod gerekli', 'Her gün 07:00-10:30 arası geçerli', 'Rezervasyon zorunlu', '0-6 yaş ücretsiz, 7 yaş ve üzeri için kod gerekli', 'İptal en geç 24 saat önce yapılmalı']::text[], 'https://grpstat.com/DealImages/G-jctfeckm/anagrsl7008.jpg', array['https://grpstat.com/DealImages/G-jctfeckm/anagrsl7008__1.jpg', 'https://grpstat.com/DealImages/G-jctfeckm/anagrsl7008__2.jpg', 'https://grpstat.com/DealImages/G-jctfeckm/anagrsl7008__3.jpg']::text[], null, 1200, '2026-12-31', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/radisson-blu-hotel-istanbul-pera/radisson-blu-pera-acik-bufe-kahvalti')
