insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('four-points-by-sheraton-istanbul-kagithane-zen-s', 'a73fad21-b65e-5c88-a8a3-595d27596dca', 'Four Points Kağıthane''de 45 dk masaj ve spa', 'spa', 'istanbul', 'Kağıthane', 'Hamidiye Mah. Cendere Cad. No:15, 34406 Kağıthane / İstanbul', '45 dakikalık masaj, sauna-buhar-hamam kullanımı ve içecek bir arada.', 'Otelin Zen Spa merkezinde İsveç, relax ya da kese-köpük seçenekli 45 dakikalık masaj yapılıyor. Pakete sauna, buhar odası ve Türk hamamı kullanımı ile bir içecek dahil. Tek kişilik ve çift kişilik seçenekleri olduğu için çiftler için de uygun.', array['Telefonla rezervasyon zorunlu', 'Hafta içi 11:00-17:00 seçenekleri daha uygun fiyatlı', 'Satın alındığı gün kullanılamaz, günlük kontenjan var', 'İptal en az 24 saat önce bildirilmeli', 'Fiyatlar T.C. vatandaşları için geçerli', 'Seçenekler 1.500 TL ile 3.700 TL arasında']::text[], 'https://grpstat.com/DealImages/G-ymiecpey/anagrsl8955.jpg', array['https://grpstat.com/DealImages/G-ymiecpey/anagrsl8955__1.jpg', 'https://grpstat.com/DealImages/G-ymiecpey/anagrsl8955__2.jpg', 'https://grpstat.com/DealImages/G-ymiecpey/anagrsl8955__3.jpg']::text[], null, 1500, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/four-points-by-sheraton-istanbul-kagithane/four-points-by-sheraton-zen-spa-masaj')
  on conflict (id) do update set isletme_id = excluded.isletme_id, baslik = excluded.baslik, kategori = excluded.kategori, sehir = excluded.sehir, semt = excluded.semt, adres = excluded.adres, kisa = excluded.kisa, aciklama = excluded.aciklama, kosullar = excluded.kosullar, gorsel = excluded.gorsel, galeri = excluded.galeri, eski_fiyat = excluded.eski_fiyat, yeni_fiyat = excluded.yeni_fiyat, bitis = excluded.bitis, stok = excluded.stok, kisi_basi_limit = excluded.kisi_basi_limit, rezervasyon_gerekli = excluded.rezervasyon_gerekli, link = excluded.link, one_cikan = excluded.one_cikan, durum = excluded.durum, kaynak = excluded.kaynak, kaynak_url = excluded.kaynak_url;
insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ramada-by-wyndham-istanbul-taksim-zen-spa', '4961677e-e1c0-5890-9ef6-7e869ac4b10e', 'Taksim Ramada Zen Spa''da masaj ve ıslak alan', 'spa', 'istanbul', 'Beyoğlu', 'Receppaşa Cad. No:15, 34437 Taksim, Beyoğlu / İstanbul', 'Taksim''de 45 dk masaj, sauna, buhar odası ve şok havuzu kullanımı.', 'Taksim''deki Ramada otelinin Zen Spa merkezinde masaj, kese-köpük ve çiftlere özel paketler sunuluyor. Paketlere şok havuzu, sauna ve buhar odası kullanımı ile soğuk bir içecek dahil. Şehir merkezinde kısa bir mola arayanlara ve çiftlere uygun.', array['Telefonla rezervasyon zorunlu', 'Islak alan kullanımı 3 saatle sınırlı', 'Fitness ve vale hizmeti dahil değil', 'Çocuk kabul edilmiyor', 'İptal en az 24 saat önce bildirilmeli', 'Seçenekler 1.100 TL ile 3.600 TL arasında']::text[], 'https://grpstat.com/DealImages/G-ygxfl3nk/anagorseell6830.jpg', array['https://grpstat.com/DealImages/G-ygxfl3nk/anagorseell6830__1.jpg', 'https://grpstat.com/DealImages/G-ygxfl3nk/anagorseell6830__2.jpg', 'https://grpstat.com/DealImages/G-ygxfl3nk/anagorseell6830__3.jpg']::text[], null, 1400, '2027-10-15', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/ramada-by-wyndham-zen-spa/ramada-by-wyndham-zen-spa-masaj')
