insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('nada-spa-ayurveda-spa-ceylon', '95c7f2f0-1237-55ab-8542-63e29a6492ea', 'Suadiye''de Ayurveda masajı: İsveç, Bali, Thai', 'spa', 'istanbul', 'Kadıköy (Suadiye)', 'Bağdat Cad. No:520 Tan Apt. D:1/C-1/D, Bostancı, Kadıköy / İstanbul', 'Sri Lanka ürünleriyle 50 dk masaj seçenekleri, hafta içi öğlen ek indirimli.', 'Bağdat Caddesi''ndeki merkezde Sri Lanka kökenli Ayurveda ürünleriyle İsveç, Bali, aromaterapi ve Thai masajı yapılıyor. Baş-boyun-omuz masajı ve yüz bakımı gibi kısa seçenekler de var. Çiftlere özel paketler kadın-erkek çiftler için tasarlanmış.', array['Hafta içi 12:00-16:30 seçenekleri %10 daha uygun', 'Kişi başı tek kod kullanılır', 'Çift paketi bir kadın ve bir erkek içindir', 'İptal en az 24 saat önce bildirilmeli', 'Seçenekler 765 TL ile 3.600 TL arasında']::text[], 'https://grpstat.com/DealImages/G-ajge3dhl/01169.jpg', array['https://grpstat.com/DealImages/G-ajge3dhl/01169__1.jpg', 'https://grpstat.com/DealImages/G-ajge3dhl/01169__2.jpg']::text[], 1900, 1710, '2026-12-15', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/spa-ceylon/nada-spa-ayurveda-masaj')
