insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ramada-by-wyndham-florya-nape-a-health-club-spa', 'a8ed894a-0f7d-5760-bf77-46e960c9c67e', 'Florya Nape''a Spa''da yarı fiyatına masaj', 'spa', 'istanbul', 'Küçükçekmece (Florya)', 'Beşyol, Birlik Cd. No:10, 34295 Küçükçekmece / İstanbul', '45 dk masaj, yüz maskesi, 2 saat ıslak alan ve içecek %50 indirimli.', 'Florya''daki Ramada otelinin spa merkezinde klasik İsveç veya relax masajı, kese-köpük ve yüz maskesi içeren paketler var. Hamam, sauna, buhar banyosu, şok duşu ve sıcak taş yataklar 2 saat kullanılabiliyor. Kadın-erkek karma bir alan; 12 yaş altı için uygun değil.', array['Rezervasyon zorunlu', 'En uygun masaj seçeneği yalnızca hafta içi 10:00-16:00', 'Islak alan kullanımı 2 saat', 'İptal en az 3 gün önce bildirilmeli', '12 yaş altı çocuklar için uygun değil', 'Seçenekler 799 TL ile 2.199 TL arasında']::text[], 'https://grpstat.com/DealImages/G-yafqrkqo/ramada21476.jpg', array['https://grpstat.com/DealImages/G-yafqrkqo/ramada21476__1.jpg', 'https://grpstat.com/DealImages/G-yafqrkqo/ramada21476__2.jpg']::text[], 2898, 1449, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/nape-spa/ramada-wyndham-florya-napea-spa-masaj-bakim')
