insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ramada-plaza-by-wyndham-istanbul-atakoy-mask-spa', '6ad44b51-9335-52f2-bd37-764cb1474b40', 'Ataköy Mask Spa''da masaj, havuz ve hamam', 'spa', 'istanbul', 'Bakırköy (Ataköy)', 'Ataköy 1. Kısım, Fişekhane Cad. No:9, 34158 Bakırköy / İstanbul', '45 dk klasik masajla kapalı havuz, sauna ve buhar odası kullanımı.', 'Ataköy''deki otelin spa merkezinde klasik ya da selülit karşıtı masaj, hamamda köpük ve kese seçenekleri bulunuyor. Pakete kapalı havuz, sauna ve buhar odası kullanımı ile su ve çay dahil. Yalnızca ıslak alan isteyenler için hafta içi ayrı bir seçenek de var.', array['Rezervasyon zorunlu', 'Islak alan ve uygulamalar toplam 2,5 saat', 'Havuzda bone zorunlu', 'Otopark ücretli', 'Yalnızca T.C. vatandaşları için geçerli', 'İptal en az 24 saat önce bildirilmeli', 'Seçenekler 899 TL ile 4.199 TL arasında']::text[], 'https://grpstat.com/DealImages/G-vr0ihzfp/a14148.jpg', array['https://grpstat.com/DealImages/G-vr0ihzfp/a14148__1.jpg', 'https://grpstat.com/DealImages/G-vr0ihzfp/a14148__2.jpg', 'https://grpstat.com/DealImages/G-vr0ihzfp/a14148__3.jpg']::text[], null, 1799, '2026-12-31', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/ramada-plaza-atakoy-mask-spa/ramada-plaza-by-wyndham-istanbul-atakoy-mask-spa-masaj-keyfi')
