insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('miracle-istanbul-asia-hotel-spa', 'a963c5f2-9eec-55f6-95b0-19eca999ae20', 'Kurtköy Miracle Asia''da 50 dk masaj ve spa', 'spa', 'istanbul', 'Pendik (Kurtköy)', 'Harmandere Mah. Dedepaşa Cad. Site Sk. No:8, Kurtköy, Pendik / İstanbul', '50 dk klasik veya Bali masajı; hamam, sauna ve buhar odası kullanımı dahil.', 'Kurtköy''deki otelin spa bölümünde 50 dakikalık klasik ya da Bali masajı ve 30 dakikalık kese-köpük seçenekleri var. Hamam, sauna, buhar odası ve fitness kullanılabiliyor; havlu, terlik ve peştamal veriliyor. Gruplar için ayrıca gelin hamamı paketi sunuluyor.', array['Rezervasyon zorunlu, en az 48 saat önceden', 'Kullanım saatleri 10:00-17:00', 'Tesis kadın-erkek karma', 'İptal en az 24 saat önce bildirilmeli', 'Kese-köpük 1.399 TL, masaj 1.999 TL']::text[], 'https://grpstat.com/DealImages/G-qjqmalv1/anagrsllllll4034.jpg', array['https://grpstat.com/DealImages/G-qjqmalv1/anagrsllllll4034__1.jpg', 'https://grpstat.com/DealImages/G-qjqmalv1/anagrsllllll4034__2.jpg', 'https://grpstat.com/DealImages/G-qjqmalv1/anagrsllllll4034__3.jpg']::text[], null, 1999, '2026-11-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/miracle-istanbul-asia-hotel-spa/miracle-istanbul-asia-hotel-spa-masaj')
