insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('aspera-hotel-altunizade-lilyum-spa', '6ee1255f-1562-5f6e-9fb5-6206d3f99e9f', 'Altunizade Lilyum Spa''da masaj ve kese-köpük', 'spa', 'istanbul', 'Üsküdar (Altunizade)', 'Altunizade, Mahir İz Cd. No:32, 34662 Üsküdar / İstanbul', '45 dk masaj, sauna ve buhar odası kullanımı ile içecek ikramı.', 'Altunizade''deki otelin Lilyum Spa merkezinde Bali, aromaterapi, İsveç ve relax masajı seçenekleri bulunuyor. Paketlere sauna ve buhar odası kullanımı ile içecek dahil; kese-köpük, peeling ve yüz maskesi içeren uzun paketler de var. Tek kişi ve çiftler için seçenek mevcut.', array['Telefonla rezervasyon zorunlu', 'Kod satın alındıktan sonra 90 gün geçerli', 'Islak alan sauna ve buhar odasından oluşuyor', 'Yalnızca T.C. vatandaşları için geçerli', 'İptal en az 24 saat önce bildirilmeli', 'Seçenekler 2.000 TL ile 6.000 TL arasında']::text[], 'https://grpstat.com/DealImages/G-li4ma4mz/as14150.jpg', array['https://grpstat.com/DealImages/G-li4ma4mz/as14150__1.jpg', 'https://grpstat.com/DealImages/G-li4ma4mz/as14150__2.jpg', 'https://grpstat.com/DealImages/G-li4ma4mz/as14150__3.jpg']::text[], null, 2000, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/aspera-hotel-altunizade-lilyum-spa/aspera-hotel-altunizade-lilyum-spa-masaj-secenekleri')
