insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ozkaymak-falez-hotel-prenses-spa', '65575f4a-ce2d-5f5a-9219-7101b3c05b0e', 'Antalya Falez''de %62''ye varan indirimli masaj', 'spa', 'antalya', 'Muratpaşa', 'Bahçelievler Mah. Tarık Akıltopu Cd. No:1, 07050 Muratpaşa / Antalya', 'Masaj, yüz maskesi, hamam-sauna ve içecek; hafta içi sabah 880 TL''den.', 'Antalya Muratpaşa''daki Özkaymak Falez otelinin Prenses Spa''sında klasik, medikal, sıcak taş ve aromaterapi masajı seçenekleri var. Tüm paketlere Türk hamamı ve sauna kullanımı, yüz maskesi ve içecek dahil. Çiftler için aromaterapi masajlı paket de bulunuyor.', array['Rezervasyon zorunlu', 'En düşük fiyatlar hafta içi 09:00-12:00 / 09:00-14:00 saatlerinde', 'Değişiklik ve iptal en az 1 gün önce', 'Seçenekler 880 TL ile 4.600 TL arasında']::text[], 'https://grpstat.com/DealImages/G-dkcctcod/01305.jpg', array['https://grpstat.com/DealImages/G-dkcctcod/01305__1.jpg', 'https://grpstat.com/DealImages/G-dkcctcod/01305__2.jpg', 'https://grpstat.com/DealImages/G-dkcctcod/01305__3.jpg']::text[], 2300, 880, '2027-01-21', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/ozkaymak-falez-otel-prenses-spa/ozkaymak-falez-hotel-masaj-secenekleri')
