insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('dr-well-estetik', '8ca348eb-ed70-59fc-a0ca-d549cc2812cb', 'Dr. Well''de 5 seans diode lazer epilasyon', 'guzellik', 'izmir', 'Karşıyaka (Bostanlı) ve 5 şube daha', 'Atakent Mah. Caher Dudayev Blv. No:163/A, Karşıyaka, İzmir (diğer şubeler: Buca, Gaziemir, Narlıdere, Bayraklı, Güzelyalı/Konak)', 'Koltuk altı, özel bölge veya yarım kol için 5 seans diode epilasyon paketi.', 'Buz başlıklı diode cihazla tek bir bölge için 5 seanslık epilasyon paketi. Koltuk altı, özel bölge ve yarım kol seçenekleri var; her alımda tek bölge seçilir. İzmir''deki 6 şubenin herhangi birinde kullanılabilir.', array['Pazartesi-Cumartesi 09:30-19:30 arası geçerli, pazar kapalı', 'Rezervasyon zorunlu', 'Kişi başı 1 kupon; aynı fırsat için tek şube kullanılır', 'Uyuşturucu krem/sprey ücrete dahil değil', 'Yüz bölgesi pakete dahil değil', 'Özel bölge paketi kadın ve erkek için ayrı; diğer paketler iki cinsiyete açık', 'İptal/değişiklik en az 1 gün önceden']::text[], 'https://grpstat.com/DealImages/G-pw4oop51/002865.jpg', '{}'::text[], 6000, 350, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/dr-well-estetik/dr-well-epilasyon-agda')
