insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('lily-s-guzellik-salonu', '9e36f482-0430-5c4a-812a-9143d39cfd32', 'Lily''s''te klasik veya Hollywood cilt bakımı', 'guzellik', 'istanbul', 'Nişantaşı / Bostancı', 'Nişantaşı: Halaskargazi Mah. Rumeli Cad. No:11 Kat:4, Şişli, İstanbul; Bostancı: Şen Apt., Tayyareci Resmi Sok. No:24, Kadıköy, İstanbul', '30 dakikalık klasik bakımdan peeling eklemeli Hollywood bakımına 7 farklı seçenek.', 'Nişantaşı ve Bostancı şubelerinde geçerli cilt bakımı paketleri. Klasik (30 dk), profesyonel (45 dk) ve Hollywood (60 dk) bakımın yanında çikolata peelingi, Sindirella bakımı, kabak ve yosun peeling seçenekleri bulunuyor. Temizlik, peeling, buhar, siyah nokta temizliği, maske ve nemlendirme gibi adımlar içeriyor.', array['Pazartesi-Cumartesi 10:00-19:30, pazar kapalı', 'Kişi başı 1 kod', 'İptal en az 48 saat önceden, aksi halde kod kullanılmış sayılır', 'Randevu telefonla alınır']::text[], 'https://grpstat.com/DealImages/G-xs41qytg/lilys-studio-nisantasi-cilt-bakimi-060861.jpg', array['https://grpstat.com/DealImages/G-xs41qytg/lilys-studio-nisantasi-cilt-bakimi-060861__1.jpg', 'https://grpstat.com/DealImages/G-xs41qytg/lilys-studio-nisantasi-cilt-bakimi-060861__2.jpg', 'https://grpstat.com/DealImages/G-xs41qytg/lilys-studio-nisantasi-cilt-bakimi-060861__3.jpg']::text[], 2000, 699, '2027-01-23', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/lily-s/lilys-studio-nisantasi-cilt-bakimi')
