insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('cinik-beauty', 'b0c7551c-d863-501f-9924-c5602b0321f4', 'Cinik Beauty''de derinlemesine veya Amerikan cilt bakımı', 'guzellik', 'istanbul', 'Nişantaşı / Şişli', 'Teşvikiye Mah. Teşvikiye Cad. Celal Derviş Apt. No:16 Kat:2 Daire:3, 34365 Şişli, İstanbul', 'Nişantaşı''nda iki seçenekli cilt bakımı: derin temizlik veya vakumlu Amerikan bakım.', 'Derinlemesine bakımda cilt analizi, temizleme, buhar, siyah nokta temizliği için peeling, cilde uygun maske ve güneş kremi uygulanıyor. Amerikan cilt bakımı ise iğnesiz, vakum destekli bir derin temizlik uygulaması. İki seçenek de tek seans.', array['Pazartesi-Cumartesi 09:00-19:00', 'Kişi başı 1 kullanım', 'Gelinmeyen randevu kullanılmış sayılır', 'İptal/değişiklik en az 1 gün önceden']::text[], 'https://grpstat.com/DealImages/G-vryhfu4e/cilt-yeni2828.jpg', array['https://grpstat.com/DealImages/G-vryhfu4e/cilt-yeni2828__1.jpg', 'https://grpstat.com/DealImages/G-vryhfu4e/cilt-yeni2828__2.jpg', 'https://grpstat.com/DealImages/G-vryhfu4e/cilt-yeni2828__3.jpg']::text[], 3000, 999, '2026-12-10', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/cinik-beauty/bakirkoy-cinik-cilt-bakim-uygulamalari')
