insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('mehry-estetik-guzellik', 'd3fa9fd1-8ff0-5557-84c4-ca30887a5b5e', 'Mehry''de klasik, Amerikan veya yosun cilt bakımı', 'guzellik', 'istanbul', 'Şişli', '19 Mayıs Mah. Büyükdere Cad. Sakarya Apt. No:6 İç Kapı No:3, Şişli, İstanbul', 'Şişli''de 399,90 TL''den başlayan tek seanslık cilt bakımı seçenekleri.', 'Klasik cilt bakımı, LED maskeli Amerikan bakım, özel ürünlerle yapılan Luxx bakım, yosun bakımı ve Baby Skin Pen seçenekleri var. Tüm seçenekler tek seans. Farklı bütçelere göre seçim yapılabiliyor.', array['Pazartesi-Cumartesi 10:00-20:00, pazar kapalı', 'Baby Skin Pen indirimli seçeneği yalnızca hafta içi 12:00-17:00', 'İptal en az 24 saat önceden, aksi halde kod kullanılmış sayılır', 'Randevu telefonla alınır']::text[], 'https://grpstat.com/DealImages/G-12suvaub/mehry-guzellik-cilt-bakimi-cf5032.jpg', array['https://grpstat.com/DealImages/G-12suvaub/mehry-guzellik-cilt-bakimi-cf5032__1.jpg', 'https://grpstat.com/DealImages/G-12suvaub/mehry-guzellik-cilt-bakimi-cf5032__2.jpg']::text[], 1000, 399.9, '2026-11-20', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/mehry-estetik-guzellik/mehry-guzellik-cilt-bakimi')
