insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ven-kuafor', '6d979ba4-737b-5e33-af3f-d4dbafd424f9', 'Ven Kuaför''de keratin bakım ve Brezilya fönü', 'guzellik', 'ankara', 'Çayyolu / Çankaya', 'Prof. Dr. Ahmet Taner Kışlalı Mah. Seyfi Saltoğlu Cad. 2715. Sok. No:2/10 B, Çayyolu, Çankaya, Ankara', 'Çayyolu''nda keratin, dolgunlaştırıcı saç bakımı veya Brezilya fönünde yarı yarıya indirim.', 'Üç saç uygulaması seçeneği var: keratin bakım, yıpranmış saçlar için dolgunlaştırıcı bakım ve saçı düz tutmaya yönelik Brezilya fönü. Yalnızca kadın müşteriler için geçerli.', array['Pazartesi-Cumartesi 08:00-19:30, pazar 10:00-19:30', 'Sadece kadınlar için', 'Kişi başı 1 kod', 'İptal en az 24 saat önceden, aksi halde kod kullanılmış sayılır']::text[], 'https://grpstat.com/DealImages/G-dn2btb1l/grsell1531.jpg', array['https://grpstat.com/DealImages/G-dn2btb1l/grsell1531__1.jpg', 'https://grpstat.com/DealImages/G-dn2btb1l/grsell1531__2.jpg', 'https://grpstat.com/DealImages/G-dn2btb1l/grsell1531__3.jpg']::text[], 3500, 1500, '2026-11-10', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/firsat/ven-kuafor-sac-uygulamalari')
