insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('tuzla-garden-hotel-spa', 'afc369ff-9461-5c69-90c5-55db2371a7d7', 'Tuzla Garden''da Spa ve Masajlı Hafta Sonu Kaçamağı', 'otel', 'istanbul', 'Tuzla', 'Cami Mah. Galipağa Sok. No: 22 Tuzla / İstanbul', 'İki kişilik 1 gece konaklama, açık büfe kahvaltı, spa ve rahatlatıcı masaj bir arada.', '2 kişi için 1 gece, şehir manzaralı standart odada konaklama. Açık büfe kahvaltı, otelin Zeosspa ıslak alanlarının kullanımı ve rahatlatıcı (relax) masaj pakete dahil. İstanbul içinde kısa bir hafta sonu dinlenmesi isteyen çiftlere uygun.', array['Yalnızca hafta sonu geçerli', 'Rezervasyon zorunlu, kod rezervasyonda bildirilir', 'Her kod tek kullanımlık', 'Giriş 14:00, çıkış 12:00', 'İptal/değişiklik en az 48 saat önceden bildirilmeli']::text[], 'https://grpstat.com/DealImages/G-73cdf9c4/tuzla-garden-hotel-konaklama-dc0a94.jpg', array['https://grpstat.com/DealImages/K-4bl23k4b/t13949.jpg', 'https://grpstat.com/DealImages/K-4bl23k4b/anagrsel3949__2.jpg', 'https://grpstat.com/DealImages/K-4bl23k4b/anagrsel3949__3.jpg']::text[], 9950, 7950, '2027-03-31', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/tuzla-garden-hotel-2/tuzla-garden-hotel-konaklama')
