insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('world-dreams-sapanca', '36e91ff3-bc77-5053-bb01-fc406ae683ca', 'Sapanca''da Jakuzili Bungalov ve Villa Konaklaması', 'otel', 'sakarya', 'Sapanca', 'Hacımercan Köy İçi Yolu No: 12 Sapanca / Sakarya', 'Tiny house''tan 6 kişilik villaya kadar Sapanca''da yarı fiyatına 1 gece konaklama.', 'Sapanca''da 1 gecelik konaklama; 2 kişilik tiny house ve 1+1 villadan 4 kişilik 2+1 ve 6 kişilik 3+1 bungalova kadar seçenek var, kahvaltılı veya kahvaltısız alınabiliyor. 1+1 ve üzeri birimlerde yatak odasında jakuzi ve salonda şömine bulunuyor (ilk odun ücretsiz). Çiftler, aileler ve arkadaş grupları için uygun.', array['Rezervasyon telefonla yapılır, tarih müsaitliğe bağlı', 'Pazar-Cuma, Cumartesi ve 14-21 Kasım ara tatili için ayrı fiyatlar var', 'Özel günler ve resmi tatillerde geçersiz', 'Giriş 14:00, çıkış 12:00', 'İptal/değişiklik en az 2 gün önceden', '2 çocuk ücretsiz, ek kişi 1.500 TL']::text[], 'https://grpstat.com/DealImages/G-quqszlz5/world-dreams-sapanca-bungalov-villa-konaklama-0369bc.jpg', array['https://grpstat.com/DealImages/G-quqszlz5/world-dreams-sapanca-bungalov-villa-konaklama-0369bc__1.jpg', 'https://grpstat.com/DealImages/G-quqszlz5/world-dreams-sapanca-bungalov-villa-konaklama-0369bc__2.jpg', 'https://grpstat.com/DealImages/G-quqszlz5/world-dreams-sapanca-bungalov-villa-konaklama-0369bc__3.jpg']::text[], 5000, 2500, '2026-12-26', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/world-dreams-sapanca/world-dreams-sapanca-bungalov-villa-konaklama')
