insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('park-inn-by-radisson-istanbul-airport', 'f2d9bdda-7624-5f42-b14c-4924371125b5', 'Park Inn Halkalı''da Havuz ve Hamam Dahil Konaklama', 'otel', 'istanbul', 'Halkalı, Küçükçekmece', 'Halkalı Merkez Mah. Fatih Cad. No: 99 Küçükçekmece / İstanbul', 'Standart odada 1 gece; havuz, sauna, hamam ve fitness kullanımı ücretsiz.', 'Standart odada 1 gece konaklama; tek ya da çift kişi aynı fiyat, 3 kişilik oda seçeneği de var. Konaklama süresince 09:00-21:00 arası hamam, havuz, sauna ve fitness alanları ücretsiz. Kahvaltı dahil değil; fuar, iş seyahati veya aktarma öncesi uygun bir seçenek.', array['Haftanın her günü geçerli, özel günler ve resmi tatiller hariç', 'Kahvaltı dahil değil', 'Rezervasyon telefonla, tarih müsaitliğe bağlı', 'Giriş 14:00, çıkış 12:00', 'İptal/değişiklik en az 2 gün önceden', 'Birden fazla kod birleştirilerek uzun konaklama yapılabilir']::text[], 'https://grpstat.com/DealImages/G-oddgurcv/01820.jpg', array['https://grpstat.com/DealImages/G-oddgurcv/01820__1.jpg', 'https://grpstat.com/DealImages/G-oddgurcv/01820__2.jpg', 'https://grpstat.com/DealImages/G-oddgurcv/01820__3.jpg']::text[], 4500, 3000, '2026-12-28', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/park-inn-by-radisson-istanbul/park-inn-radisson-istanbul-airport-konaklama')
