insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('taksim-yazici-residence', 'fdd3bb4b-5bf8-55dd-987e-e8794f12c6d6', 'Taksim''in Kalbinde İki Kişilik Rezidans Konaklaması', 'otel', 'istanbul', 'Beyoğlu, Taksim', 'İstiklal Cad., Tomtom Mah., Akansu Sok. No: 4/1 Beyoğlu / İstanbul', 'İstiklal Caddesi''ne yürüme mesafesinde deluxe oda veya suitte 1 gece.', 'İki kişi için 1 gece konaklama; deluxe oda veya suit seçilebiliyor. Kahvaltı dahil değil, istenirse kişi başı ek ücretle tabak kahvaltı veriliyor. 0-6 yaş çocuklar ücretsiz; şehir merkezinde kalmak isteyen çiftler ve turistler için uygun.', array['Özel günler hariç', 'Kahvaltı dahil değil (ücretli)', 'Rezervasyon telefonla, tarih müsaitliğe bağlı', 'İptal/değişiklik en az 3 gün önceden', '0-6 yaş çocuk ücretsiz']::text[], 'https://grpstat.com/DealImages/G-jijs2snt/taksim-yazici-residence-konaklama-bc3623.jpg', array['https://grpstat.com/DealImages/G-jijs2snt/taksim-yazici-residence-konaklama-bc3623__1.jpg', 'https://grpstat.com/DealImages/G-jijs2snt/taksim-yazici-residence-konaklama-bc3623__2.jpg', 'https://grpstat.com/DealImages/G-jijs2snt/taksim-yazici-residence-konaklama-bc3623__3.jpg']::text[], 5150, 3250, '2026-11-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/taksim-yazici-residence/taksim-yazici-residence-konaklama')
