insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('the-sign-degirmen-hotel-spa', '41aa3440-b45f-5341-aa7b-fdb471bf59a0', 'Şile''de Kahvaltılı Çift Kişilik Deniz Kenarı Kaçamak', 'otel', 'istanbul', 'Şile', 'Çavuş Mah. Plaj Sk. No: 2, 34980 Şile / İstanbul', 'Şile sahilinde kahvaltı dahil 1 gece; ekonomik odadan deniz manzaralı odaya seçenekler.', 'Çiftler için kahvaltı dahil 1 gece konaklama; standart ekonomik, şehir veya deniz manzaralı superior ve deluxe oda seçenekleri var. Kahvaltı odaya tepsi olarak servis ediliyor, yoğun günlerde açık büfe olabiliyor. Otelde hamam, sauna ve kapalı havuz var ama pakete dahil olup olmadığı sayfada net değil; masaj ve kese ücretli.', array['Özel günler hariç', 'Rezervasyon telefonla, tarih müsaitliğe bağlı', 'İptal/değişiklik en az 3 gün önceden', 'Birden fazla kod birleştirilerek çok gecelik konaklama yapılabilir', 'Masaj, kese ve köpük hizmetleri ekstra ücretli']::text[], 'https://grpstat.com/DealImages/G-u52fl2n3/anagrsel2263.jpg', array['https://grpstat.com/DealImages/G-u52fl2n3/anagrsel2263__1.jpg', 'https://grpstat.com/DealImages/G-u52fl2n3/anagrsel2263__2.jpg', 'https://grpstat.com/DealImages/G-u52fl2n3/anagrsel2263__3.jpg']::text[], 5000, 4600, '2026-12-28', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/the-sign-degirmen-otel/sile-the-sign-degirmen-hotel-spa-konaklama-paketleri')
