insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('ramada-encore-by-wyndham-izmir', '73bc2dbe-cb87-5d33-a7b8-23e91c315bf9', 'İzmir Balçova''da Kahvaltılı Hafta İçi Konaklama', 'otel', 'izmir', 'Balçova', 'Mithatpaşa Cad. No: 44 Balçova / İzmir', 'Kara veya deniz manzaralı odada, açık büfe kahvaltı dahil çift kişilik 1 gece.', 'İki kişi için 1 gece konaklama ve açık büfe kahvaltı; kara manzaralı, deniz manzaralı ve jakuzili balayı suiti seçenekleri var. Fitness salonu ve bisiklet kiralama ücretsiz, oda servisinde indirim uygulanıyor. 0-6 yaş çocuklar ücretsiz; İzmir''e iş ya da kısa tatil için gelenlere uygun.', array['Yalnızca hafta içi geçerli', 'Kongre, fuar ve özel günlerde geçersiz', 'Rezervasyon telefonla, tarih müsaitliğe bağlı', 'Giriş 14:00, çıkış 12:00', 'İptal/değişiklik en az 2 gün önceden', '0-6 yaş çocuk ücretsiz']::text[], 'https://grpstat.com/DealImages/G-l3ugsurs/38161.jpg', array['https://grpstat.com/DealImages/G-l3ugsurs/38161__1.jpg', 'https://grpstat.com/DealImages/G-l3ugsurs/38161__2.jpg', 'https://grpstat.com/DealImages/G-l3ugsurs/38161__3.jpg']::text[], 5000, 4750, '2026-11-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/ramada-encore-by-wyndham-izmir/ramada-encore-by-wyndham-izmir-konaklama-secenekleri')
