insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('nios-sapanca-bungalov', 'c96a9be1-4a71-5c0e-ac76-2bbacae8989f', 'Sapanca''da Isıtmalı Havuzlu Bungalovda Kahvaltılı Gece', 'otel', 'sakarya', 'Sapanca, Kurtköy', 'Kurtköy Yavuzselim Mah. Çetin Sok. No: 9 Sapanca / Sakarya', 'Özel ısıtmalı havuzlu ve jakuzili bungalovda iki kişilik kahvaltılı 1 gece.', '2 kişi için 1 gece, kahvaltı dahil konaklama; bungalovlarda özel ısıtmalı havuz ve jakuzi bulunuyor. Barbekü, ateş kazanı ve özel bahçe de var. Baş başa sakin bir kaçamak arayan çiftlere uygun.', array['Hafta içi ve hafta sonu için ayrı fiyat', 'Hafta sonu en az 2 gece konaklama şartı', 'Sömestr ve özel günler hariç', '14-22 Kasım ara tatili için ayrı fiyat (13.000 TL)', 'Rezervasyon telefonla, tarih müsaitliğe bağlı']::text[], 'https://grpstat.com/DealImages/G-gq0sso0x/anagrsel1919.jpg', array['https://grpstat.com/DealImages/G-gq0sso0x/anagrsel1919__1.jpg', 'https://grpstat.com/DealImages/G-gq0sso0x/anagrsel1919__2.jpg', 'https://grpstat.com/DealImages/G-gq0sso0x/anagrsel1919__3.jpg']::text[], 10000, 7500, '2026-12-25', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/nios-sapanca-bungalov/nios-sapanca-bungalovkahvalti-dahil-konaklama')
