insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('poligon-safari', '0118a219-a5ae-5c3f-9f42-72c86c08d320', 'Poligon Safari''de temel atış eğitimi ve mermi atışı', 'eglence', 'istanbul', 'Esenler', 'Yavuz Selim Mah. Yavuz Selim Sok. No:6, Esenler / İstanbul (15 Temmuz Büyük Otogar karşısı)', 'Eğitmen eşliğinde temel atış eğitimi, 400 TL''den başlayan mermi paketleriyle', 'Temel atış eğitiminin ardından seçtiğin kalibre ve adette mermiyle atış yapıyorsun; 22 kalibre, 45 ACP, 357 Magnum ve 9 mm seçenekleri var. Kendi silahı ve mermisiyle gelenler için ayrı bir paket de bulunuyor. Kafede çay ve kahve ikram ediliyor.', array['Haftanın her günü geçerli', 'Rezervasyon gerekmiyor', 'Hafta içi 09:00-23:00, hafta sonu 09:00-24:00 açık', 'Fiyat seçilen mermi paketine göre 400-3.700 TL arası değişiyor']::text[], 'https://grpstat.com/DealImages/G-rui122s4/118975.jpg', array['https://grpstat.com/DealImages/G-rui122s4/118975__1.jpg', 'https://grpstat.com/DealImages/G-rui122s4/118975__2.jpg', 'https://grpstat.com/DealImages/G-rui122s4/118975__3.jpg']::text[], null, 400, '2027-06-30', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/poligon-safari/poligon-safari-atis')
