insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('dinopark-goynuk', '5c420017-0fa0-5e9c-97b0-698b9241648e', 'Dinopark turu, su parkı ve Dinosera tek bilette', 'eglence', 'antalya', 'Kemer (Göynük)', 'Göynük, Adnan Menderes Cad. No:69, 07985 Kemer / Antalya', 'Kemer Göynük''te dinozor parkı, su parkı ve Dinosera girişi bir arada', 'Bilet; Dinopark turunu, su parkını ve Dinosera (Gülbahçesi) alanını kapsıyor. Parkta 35 gerçek boyutlu dinozor modeli, trambolin, engelli parkur, fosil kazı alanı ve macera parkuru gibi aktiviteler var; 16 yaş üstüne korku tüneli de dahil. Çocuklu aileler için tam günlük bir plan.', array['Her gün 08:30-19:00 arası geçerli', 'Rezervasyon gerekmiyor', '0-3 yaş ücretsiz, 4 yaş ve üzeri tam bilet', 'Yalnızca T.C. vatandaşları kullanabilir (99''lu geçici kimlik hariç)']::text[], 'https://grpstat.com/DealImages/G-cfrlgvk2/anagrsllson4285.jpg', array['https://grpstat.com/DealImages/G-cfrlgvk2/anagrsllson4285__1.jpg', 'https://grpstat.com/DealImages/G-cfrlgvk2/anagrsllson4285__2.jpg', 'https://grpstat.com/DealImages/G-cfrlgvk2/anagrsllson4285__3.jpg']::text[], 800, 736, '2026-12-31', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/dino-park/dino-park-giris-bileti')
