insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('funtastic-aquariums-izmir', '29502086-719e-57c2-baa0-9e0797092bb7', 'İzmir Funtastic Aquariums giriş bileti', 'eglence', 'izmir', 'Bayraklı', 'Refik Şevket İnce Mah. 2148/9 Sok. No:1/1B28 (Westpark AVM), Bayraklı / İzmir', 'Westpark AVM''deki akvaryuma indirimli çocuk ve yetişkin girişi', 'Yaklaşık 2.500 m² kapalı alanda 70''ten fazla teraryum ve binlerce su canlısını gezebileceğin akvaryum girişi. Çocuk (3-12 yaş) ve yetişkin (13+) bileti seçenekleri var. Aileler ve okul grupları için uygun.', array['Her gün 10:00-22:00 açık, kapanıştan en az 45 dk önce gidilmeli', 'Rezervasyon gerekmiyor, kod gişede gösteriliyor', '0-3 yaş ücretsiz; 13 yaş altı 18+ bir yetişkinle girmeli', 'Koi/vatoz besleme ve GreenBox fotoğraf ekstra ücretli', 'Biletler iade, iptal veya değişiklik yapılamaz']::text[], 'https://grpstat.com/DealImages/G-eeth3fae/funtastic-aquariums-izmir-giris-bileti-547ada.jpg', array['https://grpstat.com/DealImages/G-eeth3fae/funtastic-aquariums-izmir-giris-bileti-547ada__1.jpg', 'https://grpstat.com/DealImages/G-eeth3fae/funtastic-aquariums-izmir-giris-bileti-547ada__2.jpg', 'https://grpstat.com/DealImages/G-eeth3fae/funtastic-aquariums-izmir-giris-bileti-547ada__3.jpg']::text[], 669, 635, '2026-12-30', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/funtastic-aquariums-izmir/funtastic-aquariums-izmir-giris-bileti')
