insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('sandland-antalya-kum-heykel-muzesi', '5d59ae84-4bbe-5190-a347-255645d1005a', 'Sandland kum heykel müzesi girişi + içecek', 'eglence', 'antalya', 'Lara (Muratpaşa)', null, 'Lara''daki kum heykel müzesine içecek dahil giriş, çocuk biletinde %20 indirim', 'Müze girişine bir sıcak ya da soğuk içecek dahil. Hafta içi öğle saatleri için indirimli çocuk bileti, ayrıca tam gün çocuk ve yetişkin seçenekleri var. Aynı gün gece de gelinebiliyor; açık havalarda teleskopla Ay ve gezegen gözlemi ücretsiz.', array['Ziyaret her gün 09:00-21:00 arası', 'İndirimli çocuk bileti (4-12 yaş) hafta içi 12:00-17:00 için geçerli', 'Yalnızca T.C. vatandaşları kullanabilir (99''lu geçici kimlik hariç)', 'Biletler iptal ve iade edilmez']::text[], 'https://grpstat.com/DealImages/G-erlprley/0anagrsl9680.jpg', array['https://grpstat.com/DealImages/G-erlprley/0anagrsl9680__1.jpg', 'https://grpstat.com/DealImages/G-erlprley/0anagrsl9680__2.jpg', 'https://grpstat.com/DealImages/G-erlprley/0anagrsl9680__3.jpg']::text[], 270, 216, '2026-12-31', null, 5, false, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/sandland-antalya/antalya-kum-heykel-muzesi-giris')
  on conflict (id) do update set isletme_id = excluded.isletme_id, baslik = excluded.baslik, kategori = excluded.kategori, sehir = excluded.sehir, semt = excluded.semt, adres = excluded.adres, kisa = excluded.kisa, aciklama = excluded.aciklama, kosullar = excluded.kosullar, gorsel = excluded.gorsel, galeri = excluded.galeri, eski_fiyat = excluded.eski_fiyat, yeni_fiyat = excluded.yeni_fiyat, bitis = excluded.bitis, stok = excluded.stok, kisi_basi_limit = excluded.kisi_basi_limit, rezervasyon_gerekli = excluded.rezervasyon_gerekli, link = excluded.link, one_cikan = excluded.one_cikan, durum = excluded.durum, kaynak = excluded.kaynak, kaynak_url = excluded.kaynak_url;
insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('workshops-of-istanbul', 'de023226-1ec2-58ea-870c-680699265e42', 'Galata''da cam mozaik lamba atölyesi', 'spor', 'istanbul', 'Beyoğlu (Galata)', 'Bereketzade Mah. Büyük Hendek Cad. Ersoy Pasajı No:25 İç Kapı No:85, Beyoğlu / İstanbul', '2 saatlik atölyede kendi mozaik lambanı yap, eve götür', 'Eğitmen eşliğinde 2 saatlik atölyede renkleri ve deseni kendin seçerek cam mozaik bir lamba yapıyorsun; lamba seninle eve geliyor. Çay ve kahve ikramı dahil. Önceden deneyim gerekmiyor, arkadaş grupları için de uygun.', array['Rezervasyon şart, kontenjan sınırlı', 'Hafta içi 10:00/12:00/14:00/16:00, cumartesi 10:00/12:00 seansları; pazar kapalı', 'Kişi başı bir kod kullanılabilir', 'En az 48 saat önce iptal edilmezse kod kullanılmış sayılır']::text[], 'https://grpstat.com/DealImages/G-312351f0/01484.jpg', array['https://grpstat.com/DealImages/G-312351f0/01484__1.jpg', 'https://grpstat.com/DealImages/G-312351f0/01484__2.jpg', 'https://grpstat.com/DealImages/G-312351f0/01484__3.jpg']::text[], 1688, 1350, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/workshops-of-istanbul/workshops-of-istanbul-cam-mozaik-lamba-atolyesi')
