insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('anka-workshop', 'db9165bd-4b8a-540f-a9ee-a85210f54ef3', 'Kadıköy''de 2 kişilik çömlek atölyesi', 'spor', 'istanbul', 'Kadıköy', 'Osmanağa Mah. Serasker Cad. No:61/4, Kadıköy / İstanbul', 'Çarkta kendi kaseni yap: 2 kişilik atölye tek kişi fiyatına', 'Deneyim gerektirmeyen 45 dakikalık atölyede eğitmen eşliğinde çömlek çarkında kase yapıyorsun. Malzeme, müzik ve sıcak içecek dahil; parçana harf damgasıyla isim ekleyebilir, iki gün sonra isteğe bağlı boyayabilirsin. Kampanya 2 kişilik giriş için.', array['Yalnızca Kasım 2026 hafta sonları (7, 8, 14, 15, 21, 22, 28, 29 Kasım)', 'Seanslar 12:00, 14:30, 16:30, 18:30', 'Satın almadan önce telefonla yer kontrolü önerilir, sonrasında rezervasyon şart (6 çark var)', '12 yaş ve üzeri', 'Biletler iade, iptal veya değişiklik yapılamaz']::text[], 'https://grpstat.com/DealImages/G-80a1d248/14216.jpg', '{}'::text[], 3000, 1500, '2026-11-29', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/anka-workshop/anka-workshop-comlek-atolyesi')
  on conflict (id) do update set isletme_id = excluded.isletme_id, baslik = excluded.baslik, kategori = excluded.kategori, sehir = excluded.sehir, semt = excluded.semt, adres = excluded.adres, kisa = excluded.kisa, aciklama = excluded.aciklama, kosullar = excluded.kosullar, gorsel = excluded.gorsel, galeri = excluded.galeri, eski_fiyat = excluded.eski_fiyat, yeni_fiyat = excluded.yeni_fiyat, bitis = excluded.bitis, stok = excluded.stok, kisi_basi_limit = excluded.kisi_basi_limit, rezervasyon_gerekli = excluded.rezervasyon_gerekli, link = excluded.link, one_cikan = excluded.one_cikan, durum = excluded.durum, kaynak = excluded.kaynak, kaynak_url = excluded.kaynak_url;
insert into public.kampanyalar (id, isletme_id, baslik, kategori, sehir, semt, adres, kisa, aciklama, kosullar, gorsel, galeri, eski_fiyat, yeni_fiyat, bitis, stok, kisi_basi_limit, rezervasyon_gerekli, link, one_cikan, durum, kaynak, kaynak_url) values ('istanbul-dance-life', '76817e1f-5486-5b65-a100-ba0e9a84838d', '1 aylık zumba kursu, haftada 2 gün', 'spor', 'istanbul', 'Beşiktaş (Balmumcu)', 'Balmumcu Mah. Barbaros Bulvarı, Barbaros Ap. No:74 K:6 D:18, Beşiktaş / İstanbul', 'Beşiktaş''ta Latin ritimleriyle bir aylık zumba dersi %25 indirimli', 'Bir ay boyunca haftada iki gün zumba dersi. Dersler kardiyo, aerobik ve dans hareketlerini Latin müzikle birleştiriyor; sınıflar en fazla 14 kişilik. Formda kalmak isteyen ve eğlenerek spor yapmak isteyenler için.', array['Tek kişi için geçerli', 'Kayıt için önceden telefonla arama şart', 'En az 24 saat önce iptal edilmezse kod kullanılmış sayılır']::text[], 'https://grpstat.com/DealImages/G-7bff9cec/istanbul-dance-life-zumba-kursu-6cdf26.jpg', '{}'::text[], 1990, 1500, '2026-12-30', null, 5, true, null, false, 'yayinda', 'grupanya', 'https://www.grupanya.com/istanbul-dance-life/istanbul-dance-life-zumba-kursu')
